COMMENTS = {"src/rebar/_engine_support/reads.py":{"before":[[141,148],[161,164],[236,240],[275,280],[286,290],[361,364],[379,384],[416,425],[589,593]],"final":[[121,122],[135,136],[203,204],[239,240],[246,247],[311,312],[327,329],[361,364],[517,518]]},"src/rebar/attest/authorship_resolution.py":{"before":[],"final":[]},"src/rebar/graph/_links.py":{"before":[[92,97],[245,251]],"final":[[92,94],[213,214]]},"src/rebar/opcert_service/app.py":{"before":[[59,66],[77,80]],"final":[[48,50],[61,62]]},"src/rebar/opcert_service/workspace.py":{"before":[[23,30],[33,39],[141,145]],"final":[[19,21],[24,25],[120,121]]}}
DIRECTIVE_PREFIXES = ("noqa", "type:", "pyright:", "mypy:", "ruff:", "fmt:", "isort:", "pragma:", "nosec", "coverage:", "mechanism-ok:", "raw-git-ok:", "tickets-boundary-ok:", "read-via:")

def normalize(src, path):
    tree = ast.parse(src, filename=path, type_comments=True)
    def visit(node, prefix=""):
        owner = "module" if isinstance(node, ast.Module) else prefix
        body = getattr(node, "body", [])
        if owner in DOCS[path] and body and isinstance(body[0], ast.Expr) and isinstance(body[0].value, ast.Constant) and isinstance(body[0].value.value, str):
            body[0].value.value = "__ALLOWLISTED_PROSE__"
        for child in body:
            if isinstance(child, (ast.ClassDef, ast.FunctionDef, ast.AsyncFunctionDef)):
                qualified = f"{prefix}.{child.name}" if prefix else child.name
                visit(child, qualified)
    visit(tree)
    for node in ast.walk(tree):
        if isinstance(node, ast.TypeIgnore):
            node.lineno = 0
    return ast.dump(tree, include_attributes=False)

def remaining_comments(src, spans, path, side):
    tokens = [tok for tok in tokenize.generate_tokens(io.StringIO(src).readline) if tok.type == tokenize.COMMENT]
    for low, high in spans:
        assert any(low <= tok.start[0] <= high for tok in tokens), ("empty allowlisted comment range", path, side, low, high)
    return [(tok.start[1], tok.string) for tok in tokens if not any(low <= tok.start[0] <= high for low, high in spans)]

def directives(src):
    lines = src.splitlines()
    found = []
    for tok in tokenize.generate_tokens(io.StringIO(src).readline):
        if tok.type != tokenize.COMMENT:
            continue
        body = tok.string[1:].lstrip()
        if tok.string.startswith("#!") or any(body.startswith(prefix) for prefix in DIRECTIVE_PREFIXES):
            found.append(lines[tok.start[0] - 1])
    return found

for path in DOCS:
    before = subprocess.check_output(["git", "show", f"{B}:{path}"], text=True)
    final = Path(path).read_text(encoding="utf-8")
    assert normalize(before, path) == normalize(final, path), ("AST/runtime drift", path)
    assert remaining_comments(before, COMMENTS[path]["before"], path, "before") == remaining_comments(final, COMMENTS[path]["final"], path, "final"), ("non-allowlisted comment drift", path)
    assert directives(before) == directives(final), ("directive/shebang drift", path)
